<script setup lang="ts">
import StateFields from '../authoring/StateFields.vue'
import {api,newKey} from '../api'
import {useRouter} from 'vue-router'
import {ref,computed,watch,onUnmounted} from 'vue'
import {Users,Package,BookOpen,Clock3,ChevronDown,MapPin,SlidersHorizontal,MessagesSquare} from 'lucide-vue-next'
import {worldApi} from './api'
import WorldPlaces from './WorldPlaces.vue'
import CharacterAvatar from '../components/CharacterAvatar.vue'
import {useCharacterAppearance} from './character-appearance'
import {useRequestScope} from '../platform/request-scope'
import type {WorldState,WorldChange,WorldEntity} from './types'
const props=defineProps<{worldId:string;lineId?:string;checkpointId:string;state:WorldState;changes?:WorldChange[];interactive?:boolean}>(),emit=defineEmits<{correct:[];talk:[entity:WorldEntity]}>(),tab=ref('people'),expanded=ref(''),events=ref<{id:string;checkpointId:string;minute:number;description:string;type:string}[]>([])
const appearance=useCharacterAppearance()
const player=computed(()=>props.state.entities.find(e=>e.id===props.state.playerId)),people=computed(()=>props.state.entities.filter(e=>e.type==='character'&&e.id!==props.state.playerId).sort((a,b)=>Number(!!b.nearby)-Number(!!a.nearby)||a.name.localeCompare(b.name))),inventory=computed(()=>Object.entries(player.value?.state?.inventory||{}).filter(([,n])=>n>0))
function entityName(id:string){return props.state.entities.find(e=>e.id===id)?.name||'尚未辨明'}
function relationReason(entityId:string,relatedId:string){return props.state.entities.find(e=>e.id===entityId)?.state?.relationEvidence?.[relatedId]?.reason||props.changes?.find(c=>c.entityId===entityId&&c.field==='relation:'+relatedId)?.reason}
function formatChange(value:unknown):string{if(value==null)return '未知';if(typeof value==='boolean')return value?'是':'否';if(Array.isArray(value))return value.map(id=>entityName(String(id))).join('、')||'无';if(typeof value==='object'&&'name' in value)return String((value as {name:unknown}).name);if(typeof value==='object')return Object.entries(value).map(([id,v])=>`${entityName(id)}：${v}`).join('、')||'无';return String(value)}
function changeField(change:WorldChange){const f=change.field;if(f.startsWith('inventory:'))return entityName(f.slice(10));if(f.startsWith('relation:'))return '与'+entityName(f.slice(9))+'的关系';if(f.startsWith('field:'))return f.slice(6);return ({alive:'生命状态',location:'所在地点',description:'公开资料',name:'名称',traits:'特征',goal:'目标','entity:add':'新增资料','rule:deathPolicy':'死亡规则'} as Record<string,string>)[f]|| (f.startsWith('route:')?'地点连接':f.startsWith('rule:')?'世界规则':'物品')}
function sourceLabel(source:string){return ({original:'原文',inferred:'推断',game:'故事中产生',user:'你的设定'} as Record<string,string>)[source]||source}
let generation=0
const capture=useRequestScope(),router=useRouter(),chatBusy=ref(false),chatError=ref('')
let chatIntent:{body:string;key:string}|undefined
async function alone(characterId:string){if(!props.lineId||chatBusy.value)return;const scope=capture(),body={worldId:props.worldId,lineId:props.lineId,checkpointId:props.checkpointId,characterId},serialized=JSON.stringify(body);if(chatIntent?.body!==serialized)chatIntent={body:serialized,key:newKey()};chatBusy.value=true;chatError.value='';try{const result=await api<{id:string}>('/play-controls/world-chats',{method:'POST',body,key:chatIntent.key});if(scope.valid()){chatIntent=undefined;await router.push('/conversations/world/'+result.id)}}catch(e){if(scope.valid())chatError.value=(e as Error).message}finally{if(scope.valid())chatBusy.value=false}}

onUnmounted(()=>generation++)
watch(()=>[props.worldId,props.checkpointId],async()=>{const version=++generation,scope=capture();events.value=[];try{const value=await worldApi<{items:typeof events.value}>('/worlds/'+props.worldId+'/checkpoints/'+props.checkpointId+'/events',{cache:true});if(version===generation&&scope.valid())events.value=value.items}catch{/* Saved character data remains available offline. */}},{immediate:true})
</script>
<template><div class="world-details"><section class="world-player-card"><div class="row"><div class="world-character-face"><CharacterAvatar :entity-id="player?.id" :name="player?.name||'你'" :size="48"/><button v-if="interactive" class="world-appearance-link" @click="appearance?.open(player?.id)">角色形象</button></div><div><small>你在故事中</small><h2>{{player?.name}}</h2></div></div><small v-if="state.plot">开场背景</small><p>{{player?.description}}</p><p v-if="state.plot?.currentSummary">{{state.plot.currentSummary}}</p><div class="world-scene-meta"><span><MapPin :size="14"/>{{entityName(state.location)}}</span><span><Clock3 :size="14"/>{{state.timeLabel}}</span></div><StateFields v-if="player?.state?.fields" :fields="state.statusFields" :values="player.state.fields"/><p v-if="player?.state?.goal" class="world-current-goal">{{player.state.goal}}</p><p v-for="(relation,id) in player?.state?.relations" :key="id" class="world-relation">与{{entityName(String(id))}}：{{relation}}<small v-if="relationReason(state.playerId,String(id))">{{relationReason(state.playerId,String(id))}}</small></p><p v-if="state.ended" class="world-ended">这条故事暂时走到尽头</p></section><nav class="world-detail-tabs" aria-label="世界资料"><button :class="{active:tab==='people'}" @click="tab='people'"><Users :size="17"/>人物</button><button :class="{active:tab==='bag'}" @click="tab='bag'"><Package :size="17"/>背包</button><button :class="{active:tab==='lore'}" @click="tab='lore'"><BookOpen :size="17"/>资料</button><button :class="{active:tab==='events'}" @click="tab='events'"><Clock3 :size="17"/>经历</button></nav><section v-if="tab==='people'" class="world-detail-section"><p v-if="!people.length" class="muted">身边暂时没有其他人。</p><article v-for="e in people" :key="e.id" class="world-person"><button class="world-person-button" :aria-expanded="expanded===e.id" @click="expanded=expanded===e.id?'':e.id"><CharacterAvatar :entity-id="e.id" :name="e.name" :size="44"/><span><strong>{{e.name}}</strong><small>{{e.nearby?'在你身边':'曾经遇见'}}</small></span><ChevronDown :size="16"/></button><div v-if="expanded===e.id" class="world-person-details"><button v-if="interactive" class="world-appearance-link" @click="appearance?.open(e.id)">生成或更换角色形象</button><small v-if="state.plot">开场背景</small><p>{{e.description}}</p><StateFields v-if="e.state?.fields" :fields="state.statusFields" :values="e.state.fields"/><p v-if="e.traits" class="muted">{{e.traits}}</p><p v-if="e.state?.alive===false">已离世</p><p v-for="(relation,id) in e.state?.relations" :key="id">与{{entityName(String(id))}}：{{relation}}<small v-if="relationReason(e.id,String(id))" class="world-relation-reason">{{relationReason(e.id,String(id))}}</small></p><button v-if="interactive&&e.state?.alive!==false&&!state.ended" class="world-talk-target" @click="emit('talk',e)"><MessagesSquare :size="16"/>{{e.nearby?'与 TA 说话':'寻找 TA'}}</button><button v-if="lineId&&interactive" class="world-talk-target" :disabled="chatBusy" @click="alone(e.id)"><MessagesSquare :size="16"/>单独聊聊</button><small v-if="lineId&&interactive">独立对话，不改变主线进度。</small><p v-if="chatError" class="error" role="alert">{{chatError}}</p><details><summary>{{sourceLabel(e.source)}} · 来源</summary><blockquote v-for="proof in e.evidence" :key="proof.blockId">{{proof.quote}}</blockquote></details></div></article></section><section v-else-if="tab==='bag'" class="world-detail-section"><p v-if="!inventory.length" class="muted">暂时没有确认持有的物品。</p><article v-for="[id,count] in inventory" :key="id" class="world-bag-item"><Package :size="19"/><div><strong>{{entityName(id)}}</strong><small>{{state.entities.find(e=>e.id===id)?.description}}</small></div><span>× {{count}}</span></article></section><section v-else-if="tab==='lore'" class="world-detail-section"><p v-if="!state.lore.length&&!state.entities.some(e=>e.type!=='character')" class="muted">探索之后，见闻会留在这里。</p><WorldPlaces :state="state"/><details v-for="l in state.lore" :key="l.id" class="world-lore"><summary>{{l.title}}</summary><p>{{l.text}}</p><small>{{sourceLabel(l.source)}}</small><blockquote v-for="proof in l.evidence" :key="proof.blockId">{{proof.quote}}</blockquote></details><details v-for="e in state.entities.filter(e=>['place','item','faction'].includes(e.type))" :key="e.id" class="world-lore"><summary>{{e.name}}</summary><p>{{e.description}}</p><p v-if="state.rules.routes?.[e.id]?.length" class="world-place-links"><MapPin :size="14"/> 可通往 <span v-for="id in state.rules.routes[e.id]" :key="id">{{entityName(id)}}</span></p><small>{{sourceLabel(e.source)}}</small></details></section><section v-else class="world-detail-section"><p v-if="!events.length" class="muted">新的经历会留在这里。</p><article v-for="e in events.slice().reverse()" :key="e.id" class="world-event"><small>故事时间 +{{e.minute}} 分钟</small><p>{{e.description}}</p></article></section><details v-if="changes?.length" class="world-changes"><summary>这一轮的变化 <span>{{changes.length}}</span></summary><p v-for="(c,i) in changes" :key="i"><strong>{{c.entityId?entityName(c.entityId):'世界'}}</strong><span v-if="c.itemId"> {{entityName(c.itemId)}} × {{c.quantity}}</span><span v-else> · {{changeField(c)}}：{{formatChange(c.before)}} → {{formatChange(c.after)}}</span><small>{{c.reason}}</small></p></details><button v-if="interactive" class="world-correct-link" @click="emit('correct')"><SlidersHorizontal :size="16"/>调整世界资料</button></div></template>

<style scoped>.world-character-face{display:grid;justify-items:center;gap:6px}.world-appearance-link{font-size:12px;min-height:30px;padding:4px 8px;color:var(--accent);background:transparent;border:0}</style>
